/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { SelectControl } from '@wordpress/components';
import { useSelect } from '@wordpress/data';
import type { CategoryId } from '../../types';

type CategoryRecord = {
	id: number;
	name: string;
};

type CategoryPickerProps = {
	selectedCats: CategoryId[];
	onSelected: ( selected: CategoryId[] ) => void;
};

const CategoryPicker = ( { selectedCats, onSelected }: CategoryPickerProps ) => {
	const categories = useSelect( ( select ) =>
		(
			select( 'core' ) as {
				getEntityRecords: (
					kind: string,
					name: string,
					query: { per_page: number }
				) => CategoryRecord[] | null;
			}
		).getEntityRecords( 'taxonomy', 'category', {
			per_page: 100,
		} )
	);

	const isLoading = useSelect( ( select ) => {
		return (
			select( 'core/data' ) as {
				isResolving: (
					store: string,
					selector: string,
					args: [ string, string, { per_page: number } ]
				) => boolean;
			}
		).isResolving( 'core', 'getEntityRecords', [
			'taxonomy',
			'category',
			{ per_page: 100 },
		] );
	} );

	if ( isLoading ) {
		return <h3>{ __( 'Loading categories…', 'jcl_i18n' ) }</h3>;
	}

	if ( categories === null ) {
		return <p>No categories found</p>;
	}

	return (
		<SelectControl
			hideLabelFromVision
			multiple
			options={ categories.map( ( { id, name } ) => ( {
				label: name,
				value: id,
			} ) ) }
			onChange={ ( selected ) => {
				onSelected( selected as CategoryId[] );
			} }
			style={ { minWidth: '250px', height: '100px' } }
			value={ selectedCats }
		/>
	);
};

export default CategoryPicker;
