/**
 * WordPress dependencies
 */
import { useState } from '@wordpress/element';
import type { Dispatch, SetStateAction } from '@wordpress/element';
import apiFetch from '@wordpress/api-fetch';
import type { ApiResponse, Config } from '../../../types';

/**
 * Internal dependencies
 *
 * @param {string} url
 */
type UseApiResult< T > = {
	apiClient: ( config: Config, parent?: number ) => Promise< void >;
	data: T | null;
	error: unknown;
	loading: boolean;
	setLoading: Dispatch< SetStateAction< boolean > >;
};

export default function useApi< T = ApiResponse >(
	url: string
): UseApiResult< T > {
	const [ data, setData ] = useState< T | null >( null );
	const [ error, setError ] = useState< unknown >( null );
	const [ loading, setLoading ] = useState( false );

	/* global jclCurrentCat */
	const apiClient = async function (
		config: Config,
		parent = 0
	): Promise< void > {
		setLoading( true );

		const params = new URLSearchParams( {
			orderby: String( config.orderby ),
			orderdir: String( config.orderdir ),
			parent: String( parent ),
			showEmpty: String( config.show_empty ),
			taxonomy: 'category',
			type: 'post',
		} );

		if (
			typeof jclCurrentCat !== 'undefined' &&
			Number( config.onlycategory ) > 0
		) {
			params.append( 'currentCat', jclCurrentCat );
		}

		if ( config.categories ) {
			params.append( 'exclusionType', String( config.include_or_exclude ) );
			params.append(
				'cats',
				Array.isArray( config.categories )
					? config.categories.join( ',' )
					: String( config.categories )
			);
		}

		return apiFetch( { path: `${ url }?${ params.toString() }` } )
			.then( ( response ) => {
				setData( response as T );
				setLoading( false );
			} )
			.catch( ( e ) => {
				setLoading( false );
				setError( e );
			} );
	};

	return { apiClient, data, error, loading, setLoading };
}
